121: // PINS: journey-log chronology, as consumed by render.js's #journey-log.
122: // Entries carry the run key (run, hop): top-down, a run completed later
123: // floats wholly above a run completed earlier, and inside a run the entries
124: // sort hop-ascending whatever emission order the trace engine produces —
125: // a 4-hop trace must never read "hop 2/4" above "hop 1/4" (named
126: // counter-example, pinned in test/panel/render.test.js).
127: export function journeyEntryIsBefore(entry, existing) {
128:   return entry.run > existing.run || (entry.run === existing.run && entry.hop < existing.hop);
129: }
