131: // Pure insertion into a sorted journey list (no DOM here): returns the
132: // ordered array with the new entry placed so the run key order holds.
133: export function orderJourneyEntries(entries, entry) {
134:   const ordered = [...entries];
135:   const index = ordered.findIndex((existing) => journeyEntryIsBefore(entry, existing));
136:   if (index === -1) ordered.push(entry);
137:   else ordered.splice(index, 0, entry);
138:   return ordered;
