// DOCUMENTS: the Stage 6 component — an authoritative DNS resolver with a
// tick-TTL cache ledger. The authoritative table is in-component
// (example.com -> 10.1; Stage 6b adds the CDN name). A lookup consults the
// table only on a cache miss or an expired entry: a hit inside ttlTicks is
// an incrementing cachedHits with NO authoritative consult, exactly like
// cache.js's Map lookup — never a probability.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP, a ttlTicks that is not a positive integer, and a record table
// whose name is empty or whose target is not a mini-IP (fail-loud over
// silent mis-configuration). An unknown name answers { status: 'NX' } —
// never a throw at the DNS layer; the throw rule belongs to cross-subnet
// addresses (router.js).
export function createDns({
  address = '10.60',
  ttlTicks = 300,
  records = { 'example.com': '10.1' },
} = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  for (const [name, target] of Object.entries(records)) {
    if (typeof name !== 'string' || name.trim() === '') {
      throw new Error('dns: record names must be non-empty strings');
    }
    if (!/^\d+\.\d+$/.test(String(target))) {
      throw new Error(`dns: record ${name} targets invalid mini-IP ${target}`);
    }
  }
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let lastLookup = null;

  // An entry answers from the ledger only while currentTick is strictly
  // before its expiry: cached at tick T with ttlTicks = 300 means alive
  // through tick T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) {
        cache.delete(entry.name);
      }
    }
  }

  function lookup(name, currentTick = 0) {
    if (typeof name !== 'string' || name.trim() === '') {
      throw new Error(`dns: lookup name must be a non-empty string, got ${name}`);
    }
    lookups += 1;
    evictExpired(currentTick);
    const entry = cache.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', atTick: currentTick };
      return { status: 'HIT', target: entry.target };
    }
    // Miss or expired entry: the authoritative table answers, and the reply
    // refills the ledger with a fresh TTL.
    authoritative += 1;
    const target = records[name];
    if (!target) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'AUTH', atTick: currentTick };
    return { status: 'AUTH', target };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      lastLookup,
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router joining the 10.x
// and 20.x network instances at its two interfaces (10.65 on the left, 20.1
// on the right). Any frame addressed outside its own subnet rides exactly
// one router hop (the routed counter), then the far network resolves the
// target with its own fail-loud rule — a send into subnet 20 to an
// unregistered host (20.9) throws from the far network's resolve, mirroring
// network.js today. Same-subnet sends never touch the router.
//
// CHECKS: the constructor rejects an interface that is not a two-number
// mini-IP and both interfaces sitting on the same subnet (a router with one
// subnet is a defect, not a hub).
const MINI_IP = /^\d+\.\d+$/;

const netOf = (addr) => Number(String(addr).split('.')[0]);

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!MINI_IP.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP leftAddress ${leftAddress}`);
  }
  if (!MINI_IP.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP rightAddress ${rightAddress}`);
  }
  const leftNet = netOf(leftAddress);
  const rightNet = netOf(rightAddress);
  if (leftNet === rightNet) {
    throw new Error(`router: both interfaces sit on subnet ${leftNet}`);
  }
  let left = null;
  let right = null;
  let routed = 0;
  let lastFrame = null;

  const self = {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    // Joins the two networks and registers the router itself at each
    // interface address, so the 20-side edge (20.1 in Stage 6a — the only
    // reachable 20.x target until Stage 6b parks the CDN edge there) answers
    // a direct send instead of failing.
    join(leftNetwork, rightNetwork) {
      leftNetwork.registerServer(leftAddress, self);
      rightNetwork.registerServer(rightAddress, self);
      left = leftNetwork;
      right = rightNetwork;
    },

    // The wire-visible reply at the router's own interface. The 20-side edge
    // is the reachable cross-subnet target in 6a, so the reply names it.
    handleRequest(request = 'GET /') {
      return '200 Router 20.1';
    },

    // One router hop: pick the joined network that owns the target's subnet,
    // count the hop, and hand the frame over unchanged — the far network
    // applies its own resolve (and its own loud throw for 20.9).
    route({ from, to, request }) {
      const net = netOf(to);
      const peer = net === rightNet ? right : net === leftNet ? left : null;
      if (!peer) {
        throw new Error(`router: no route to subnet ${net} (joined ${leftNet} and ${rightNet})`);
      }
      routed += 1;
      lastFrame = `${from} -> ${to} | routed cross-subnet (${request})`;
      return peer.send({ from, to, request });
    },

    routeToQueue(frame) {
      const net = netOf(frame.to);
      const peer = net === rightNet ? right : net === leftNet ? left : null;
      if (!peer) {
        throw new Error(`router: no route to subnet ${net} (joined ${leftNet} and ${rightNet})`);
      }
      routed += 1;
      lastFrame = `${frame.from} -> ${frame.to} | routed cross-subnet (${frame.request})`;
      peer.deliverToQueue(frame);
    },

    snapshot() {
      return { leftAddress, rightAddress, routed, lastFrame };
    },
  };
  return self;
}

