// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds optional
// cross-subnet routing: a network declared with a subnet number hands any
// frame addressed outside that subnet to its attached Router (exactly one
// router hop), while undeclared networks keep the single-fabric behavior —
// resolve throws for any unknown host.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud.
const MINI_IP = /^\d+\.\d+$/;

const netOf = (addr) => Number(String(addr).split('.')[0]);

export function createNetwork({ subnet = null } = {}) {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // CHECKS: the cross-subnet branch conditions on the declared subnet —
  // same-subnet targets resolve locally as always, foreign targets need an
  // attached router (loud throw without one), and an undeclared network
  // (subnet === null) keeps today's single-fabric behavior untouched.
  function gatewayFor(to) {
    if (subnet === null) return null;
    const net = netOf(to);
    if (net === subnet) return null;
    if (!router) {
      throw new Error(`network: no route to subnet ${net} — no router attached`);
    }
    return router;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(attached) {
      router = attached;
    },

    send({ from, to, request }) {
      validate(from);
      validate(to);
      const gateway = gatewayFor(to);
      if (gateway) return gateway.route({ from, to, request });
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      const gateway = gatewayFor(to);
      if (gateway) {
        gateway.routeToQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

// DOCUMENTS: the Stage 6 hop-by-hop trace machine — branches on whether the
// browser path carries a host ("example.com/about") or is host-less
// ("/about"). Host-less runs delegate to an inner Stage 5 machine, so the
// Stage 5 hop story stays byte-identical: no DNS hop, no cross-subnet hop.
// A hosted run spends exactly two DNS hops — the Browser ask, then the DNS
// answer — before the browser emits the GET with the resolved mini-IP
// target, riding the same Stage 5 chain underneath (outer hop = inner + 2).
// An unknown name answers "NX no record" and the run ends at the answer:
// the browser renders the NX card and never emits a GET.
//
// CHECKS: the machine is constructed only for Stage 6 (the engine wires it
// there); the inner machine keeps its own Stage 5 validation.
import { createTraceMachine } from './trace.js';

// CHECKS: the hosted-path grammar splits on the first "/" — a path that
// starts with "/" carries no host; anything else names one. Named
// counter-example: "/about" yields host null (the Stage 5 story),
// "example.com/about" yields host "example.com" + hostPath "/about", and a
// bare "example.com" reads as host with root path "/".
export function splitHostPath(path = '/') {
  const raw = String(path);
  if (raw.startsWith('/')) return { host: null, hostPath: raw };
  const cut = raw.indexOf('/');
  if (cut === -1) return { host: raw, hostPath: '/' };
  return { host: raw.slice(0, cut), hostPath: raw.slice(cut) };
}

const BLANK_TRACE = {
  targetServer: null,
  cacheStatus: null,
  dbOp: null,
  dbStale: false,
  asyncJob: false,
  response: null,
  status: null,
  body: null,
  routeId: null,
};

export function createStage6Trace({
  serverAddress,
  servers,
  lb,
  network,
  cache,
  database,
  workerQueue,
  dns,
  bumpTick,
  getTick,
  onServe,
  onFinish,
}) {
  if (!dns) {
    throw new Error('trace: stage 6 needs the DNS resolver attached');
  }
  // The inner Stage 5 machine owns the post-DNS hop chain verbatim: same
  // frames, same queue machinery, same served-record handling.
  const inner = createTraceMachine({
    stage: 5,
    serverAddress,
    servers,
    lb,
    network,
    cache,
    database,
    workerQueue,
    bumpTick,
    getTick,
    onServe,
    onFinish,
  });

  // run === null means a host-less run is live (or none started yet);
  // otherwise the hosted run's state rides here. The inner machine's hop
  // count maps onto the outer one with the +2 DNS offset while chained.
  let run = null;

  function dnsAnswerText() {
    return `${run.dnsTarget} (${run.dnsStatus === 'HIT' ? 'cache HIT' : 'authoritative'})`;
  }

  function startRun({ method = 'GET', path = '/about', from = '10.2' } = {}) {
    const parsed = splitHostPath(path);
    if (!parsed.host) {
      run = null;
      return inner.step({ method, path, from });
    }
    run = {
      host: parsed.host,
      hostPath: parsed.hostPath,
      method,
      from,
      request: `${method} ${parsed.hostPath}`,
      dnsStatus: null,
      dnsTarget: null,
      hop: 1,
      done: false,
      nx: false,
    };
    return `Browser (${from}) asks DNS (${dns.address}) for "${parsed.host}"`;
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const innerHop = inner.snapshot().hop;
      if (run === null || run.done || innerHop >= 8) {
        return startRun({ method, path, from });
      }
      if (run.hop === 1) {
        // Hop 2: the DNS resolver answers from its ledger or its table — a
        // live-entry hit, an authoritative fill, or the NX dead end.
        const result = dns.lookup(run.host, getTick());
        run.hop = 2;
        if (result.status === 'NX') {
          run.done = true;
          run.nx = true;
          onFinish({
            from: dns.address,
            to: run.from,
            request: `DNS ${run.host}`,
            response: 'NX no record',
          });
          return `DNS (${dns.address}) -> Browser (${run.from}) | NX no record`;
        }
        run.dnsStatus = result.status;
        run.dnsTarget = result.target;
        return `DNS (${dns.address}) -> Browser (${run.from}) | ${dnsAnswerText()}`;
      }
      // Hosted resolved run, outer hops 3..10: the inner Stage 5 machine
      // walks its chain with the host path (outer hop = inner hop + 2).
      return inner.step({ method: run.method, path: run.hostPath, from: run.from });
    },

    snapshot() {
      const innerSnap = inner.snapshot();
      if (!run) {
        return { ...innerSnap, host: null, dnsName: null, dnsStatus: null, dnsTarget: null };
      }
      const dnsFields = {
        host: run.host,
        dnsName: run.host,
        dnsStatus: run.dnsStatus,
        dnsTarget: run.dnsTarget,
      };
      if (run.nx) {
        return {
          hop: 2,
          method: run.method,
          path: run.hostPath,
          from: run.from,
          request: `DNS ${run.host}`,
          ...BLANK_TRACE,
          response: 'NX no record',
          status: 'NX',
          body: 'no record',
          ...dnsFields,
        };
      }
      if (innerHop0InHostedRun(run, innerSnap)) {
        return {
          hop: run.hop,
          method: run.method,
          path: run.hostPath,
          from: run.from,
          request: run.request,
          ...BLANK_TRACE,
          ...dnsFields,
        };
      }
      return { ...innerSnap, hop: innerSnap.hop + 2, ...dnsFields };
    },
  };
}

// The DNS-only phase of a hosted run: the inner machine has not started its
// chain yet (hop 0), so the outer trace reads the ask or the answer hop.
function innerHop0InHostedRun(run, innerSnap) {
  return innerSnap.hop === 0;
}

