// DOCUMENTS: pure presentation model — engine snapshot in, labels and bar
// geometry out. No DOM here: this is what the unit suite pins; panel.js and
// render.js own all DOM writes.
import { splitHostPath } from '../sim/trace-stage6.js';

export const TICK_MS = 100;
const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
// Total hops per stage's fixed trace shape (trace.js and engine.traceHop
// agree). Stage 6 is per-trace instead: totalHopsForTrace below.
const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8 };

// CHECKS: Stage 6's hop total conditions on the trace itself — a hosted
// path spends exactly two DNS hops on top of the Stage 5 chain (10), an
// unknown host ends at the NX answer (2), and a host-less path keeps the
// Stage 5 count (8) with byte-identical hop texts. Counter-example: a
// Stage 6 "GET /about" trace reads 8 hops with the Stage 5 sentences.
export function totalHopsForTrace(stage, trace = null) {
  if (stage !== 6) return TOTAL_HOPS[stage] ?? 4;
  if (trace?.host) return trace.dnsStatus === 'NX' ? 2 : 10;
  return 8;
}

// Upper bound of a Stage 6 trace for a typed path, before the DNS ledger
// has answered: hosted runs may chain the full 10; host-less runs stay 8.
// The per-trace total (totalHopsForTrace) ends loops early on the NX path.
export function totalHopsUpperBound(stage, path = '/about') {
  if (stage !== 6) return TOTAL_HOPS[stage] ?? 4;
  return splitHostPath(path).host ? 10 : 8;
}

