  if (!ringSpecs) {
    throw new Error(`layout: unknown stage ${stage} (expected 1-6)`);
  }
  const gap = Math.round(ringGap);
  return ringSpecs.map(([id, label], k) => ({ id, radius: (k + 1) * gap, label }));
}

