// DOCUMENTS: wire-lane anchor config, split from viewport.js by
// responsibility (guard-file-size). Each wire lane sits on its wire in world
// coordinates (col-left on browser↔network, col-right on
// network↔webserver/lb, lb-backends centered between the two backend wires,
// servers-cache centered between the two cache wires). A value may pin a
// lane at a fraction t down its wire: Stage 5+ anchors the cache→db lane at
// t=0.3 so it clears the queue→worker crossing. Stage 6 anchors the DNS
// ask/answer lane on the browser↔DNS wire.
export const LANE_WIRES = {
  1: { 'wire-col-left': 'wire-browser-network', 'wire-col-right': 'wire-network-webserver' },
  2: { 'wire-col-left': 'wire-browser-network', 'wire-col-right': 'wire-network-lb' },
