export function stage5Parts(t) {
  const backendCard = t?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = t?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  const owners = t?.asyncJob ? {...} : {...};
  const lanes = t?.asyncJob ? {...} : {...};
  return { owners, lanes };
}

export function stage6HopTarget(snapshot) {
  const t = snapshot.trace ?? {};
  if (t.host && t.dnsStatus === 'NX') {
    const owners = { 1: 'node-browser', 2: 'node-dns' };
    const lanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
    return { cardId: owners[t.hop] ?? 'node-browser', laneId: lanes[t.hop] ?? 'packet-req-dns' };
  }
  if (t.host) {
    const dns = { 1: 'node-browser', 2: 'node-dns' };
    const dnsLanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
    if (t.hop <= 2) return { cardId: dns[t.hop] ?? 'node-browser', laneId: dnsLanes[t.hop] ?? 'packet-req-dns' };
    const { owners, lanes } = stage5Parts(t);
    const innerHop = t.hop - 2;
    return { cardId: owners[innerHop] ?? 'node-browser', laneId: lanes[innerHop] ?? 'packet-req-left' };
  }
  const { owners, lanes } = stage5Parts(t);
  return { cardId: owners[t.hop] ?? 'node-browser', laneId: lanes[t.hop] ?? 'packet-req-left' };
}
