// Single hop of the trace; the engine moves the request one stage per call,
// originating from whichever browser is currently expanded on Ring 3. The
// journey label reads the per-trace hop total (Stage 6 branches: 10 hosted,
// 8 host-less, 2 NX).
function stepOneHop() {
  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  const totalHops = totalHopsForTrace(snapshot.stage, snapshot.trace);
  // PINS: hop 1 emission starts a new trace run — that run (whole, hops
  // ascending) floats above the previous run in #journey-log.
  if (snapshot.trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${snapshot.trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: snapshot.trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

$('btn-next-hop').addEventListener('click', stepOneHop);

$('btn-play-request').addEventListener('click', () => {
  if (timer) pause();
  // The bound reads the typed path (Stage 6 hosted runs may chain 10 hops);
  // the per-trace total ends the run early on the NX path.
  const bound = totalHopsUpperBound(currentStage, els.urlInput.value);
  const iv = setInterval(() => {
    const snap = stepOneHop();
    if (snap.trace.hop >= totalHopsForTrace(snap.stage, snap.trace) || snap.trace.hop >= bound) {
      clearInterval(iv);
    }
  }, TICK_MS);
});

$('btn-url-go').addEventListener('click', () => {
  if (timer) pause();
  const bound = totalHopsUpperBound(currentStage, els.urlInput.value);
  for (let i = 0; i < bound + 1; i += 1) {
    const snap = stepOneHop();
    if (snap.trace.hop >= totalHopsForTrace(snap.stage, snap.trace)) break;
  }
});

