import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  it('answers a hit inside ttlTicks from the ledger and re-reads the table once the entry expires', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    // cold: authoritative
    expect(dns.lookup('example.com', 5)).toEqual({ status: 'AUTH', target: '10.1' });
    let snap = dns.snapshot(5);
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1, address: '10.60', ttlTicks: 300 });
    expect(snap.cache).toEqual([{ name: 'example.com', target: '10.1', expiresAtTick: 305, ttlRemaining: 300 }]);
    // PINS (negative-case contract): a hit inside ttlTicks increments
    // cachedHits and consults the authority NO second time — the snapshot's
    // authoritative counter stays at 1.
    expect(dns.lookup('example.com', 304)).toEqual({ status: 'HIT', target: '10.1' });
    snap = dns.snapshot(304);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });
    // CHECKS: the tick the TTL names is the first tick the entry is gone —
    // an expired entry must NOT be answered from the ledger: the table is
    // consulted again (authoritative +1) and the entry refills fresh.
    expect(dns.lookup('example.com', 305)).toEqual({ status: 'AUTH', target: '10.1' });
    snap = dns.snapshot(305);
    expect(snap).toMatchObject({ lookups: 3, cachedHits: 1, authoritative: 2 });
    expect(snap.cache[0]).toEqual({ name: 'example.com', target: '10.1', expiresAtTick: 605, ttlRemaining: 300 });
  });

  it('answers NX for unknown names without throwing, and validates its config', () => {
    const dns = createDns();
    expect(dns.lookup('nope.example', 0)).toEqual({ status: 'NX' });
    expect(dns.snapshot(0)).toMatchObject({ lookups: 1, authoritative: 1, cachedHits: 0 });
    expect(dns.snapshot(0).cache).toEqual([]);  // NX fills nothing
    // CHECKS: fail-loud config validation
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 1.5 })).toThrow(/ttlTicks/);
    expect(() => createDns({ records: { 'example.com': '101' } })).toThrow(/invalid mini-IP/);
    expect(() => dns.lookup('')).toThrow(/non-empty string/);
  });
});
```

