describe('createRouter + cross-subnet networks', () => {
  it('routes cross-subnet sends through exactly one router hop and keeps same-subnet sends unchanged', () => {
    const net10 = createNetwork({ subnet: 10 });
    const net20 = createNetwork({ subnet: 20 });
    const server = createWebServer({ address: '10.1' });
    net10.registerServer('10.1', server);
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    router.join(net10, net20);
    net10.attachRouter(router);
    net20.attachRouter(router);

    // same-subnet: unchanged send contract, router never touched
    expect(net10.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2', to: '10.1', request: 'GET /about', response: '200 This is the about page',
    });
    expect(router.snapshot().routed).toBe(0);

    // cross-subnet: one hop via the router; 20.1 (the router's 20-side) is the only reachable 20.x target in 6a
    const frame = net10.send({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(frame.response).toBe('200 Router 20.1');
    expect(router.snapshot().routed).toBe(1);
    expect(router.snapshot().lastFrame).toBe('10.2 -> 20.1 | routed cross-subnet (GET /)');
  });

  it('fails loud for unregistered 20.x hosts and unjoined routers', () => {
    const net10 = createNetwork({ subnet: 10 });
    const net20 = createNetwork({ subnet: 20 });
    const router = createRouter();
    router.join(net10, net20);
    net10.attachRouter(router);
    net20.attachRouter(router);
    // PINS (negative-case contract): 20.9 throws — the failure is loud.
    expect(() => net10.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(/no server at 20\.9/);
    // no router attached: foreign subnet fails at the gateway
    const lone = createNetwork({ subnet: 10 });
    expect(() => lone.send({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(/no route to subnet 20/);
    // constructor validation
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '20.1.1' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.1' })).toThrow(/same subnet/);
  });

  it('stage 6 engine exposes DNS 10.60 and the Router and keeps stage 1-5 snapshots free of them', () => {
